import { z } from 'zod';
const patientBody = z.object({ firstName: z.string().trim().min(1).max(100), middleName: z.string().trim().max(100).optional().or(z.literal('')), lastName: z.string().trim().min(1).max(100), dob: z.coerce.date().max(new Date()), gender: z.string().min(1).max(40), bloodGroup: z.string().max(10).default('Unknown'), phone: z.string().trim().min(8).max(30), email: z.union([z.email(), z.literal('')]).optional(), city: z.string().trim().max(100).optional(), emergencyContact: z.string().trim().max(200).optional(), allergies: z.array(z.string().trim().min(1).max(100)).max(50).default([]), status: z.enum(['Active', 'Inactive']).default('Active') });
const envelope = (body) => z.object({ body, query: z.object({}).passthrough(), params: z.object({}).passthrough() });
export const createPatientSchema = envelope(patientBody);
export const updatePatientSchema = envelope(patientBody.partial());
export const patientIdSchema = z.object({ body: z.unknown(), query: z.object({}).passthrough(), params: z.object({ id: z.uuid() }) });
export const patientListSchema = z.object({ body: z.unknown(), params: z.object({}).passthrough(), query: z.object({ page: z.coerce.number().int().min(1).default(1), page_size: z.coerce.number().int().min(1).max(100).default(20), search: z.string().max(100).optional(), status: z.enum(['Active', 'Inactive']).optional(), sort_by: z.enum(['createdAt', 'firstName', 'lastName', 'mrn']).default('createdAt'), sort_order: z.enum(['asc', 'desc']).default('desc') }) });
